function validarCorreo(t){if("string"!=typeof t)return!1;return/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(t.trim())}function soloLetras(t){if("string"!=typeof t||""===t.trim())return!1;return/^[a-zA-ZáéíóúÁÉÍÓÚñÑüÜ\s]+$/.test(t)}function validarLongitud(t,e){if(null==t)return!1;const r=String(t).replace(/[^0-9]/g,"");return 0!==r.length&&r.length<=e}function calcularEdad(t){const e=new Date(t);if(isNaN(e.getTime()))return NaN;const r=new Date;let n=r.getFullYear()-e.getFullYear();const a=r.getMonth()-e.getMonth();return(a<0||0===a&&r.getDate()<e.getDate())&&n--,n}function esMayorDeEdad(t){const e=calcularEdad(t);return!isNaN(e)&&e>=18}function validarPassword(t){if("string"!=typeof t)return!1;const e=/[A-Z]/.test(t),r=/[a-z]/.test(t),n=/[0-9]/.test(t),a=/[^A-Za-z0-9]/.test(t),i=t.length>=8;return e&&r&&n&&a&&i}function formatearTelefono(t){if("string"!=typeof t&&"number"!=typeof t)return null;const e=String(t).replace(/\D/g,"");if(10!==e.length)return null;return`(${e.slice(0,3)}) ${e.slice(3,6)}-${e.slice(6,10)}`}function capitalizarPalabras(t){return"string"!=typeof t?"":t.trim().toLowerCase().split(/\s+/).map(t=>t.charAt(0).toUpperCase()+t.slice(1)).join(" ")}